mapper.select:

  SELECT /* getAlimIconList */
         P.*
    FROM (  SELECT 
                 , ROW_NUMBER() OVER (ORDER BY C.SORT_ORDR, C.COMD_CODE) AS ROW_NUMB
              FROM TB_CODEXD C

             WHERE C.COMM_CODE = #{alimSitu}

         ) P
   WHERE P.ROW_NUMB BETWEEN #{startRow} AND #{endRow}
ORDER BY P.ROW_NUMB


SELECT /* getAlimIconDtl */

  FROM TB_CODEXD C

 WHERE C.COMM_CODE = #{alimSituCode}
   AND C.COMD_CODE = #{alimSitu}


SELECT /* getAlimSituCodeCount */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{alimSituCode}
   AND COMD_CODE = #{alimSitu}

mapper.insert:
/* saveAlimIcon */
INSERT INTO TM_ALICON (
            ALIM_SITU
          , MIME_TYPE
          , ICON_DATA
          , FILE_SIZE
          , PIXL_WDTH
          , PIXL_HGHT
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{alimSitu}
          , #{mimeType}
          , #{iconData}
          , #{fileSize}
          , #{pixlWdth}
          , #{pixlHght}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
) AS NEW_ICON
ON DUPLICATE KEY UPDATE
       MIME_TYPE = NEW_ICON.MIME_TYPE
     , ICON_DATA = NEW_ICON.ICON_DATA
     , FILE_SIZE = NEW_ICON.FILE_SIZE
     , PIXL_WDTH = NEW_ICON.PIXL_WDTH
     , PIXL_HGHT = NEW_ICON.PIXL_HGHT
     , UPDT_ADMN = NEW_ICON.UPDT_ADMN
     , UPDT_DATE = CURRENT_TIMESTAMP
